        public static bool IsLetter(char value)
        {
            if (value < 128) return (value >= 'A' && value <= 'Z') || (value >= 'a' && value <= 'z');
            return InRanges(value, LetterStarts, LetterEnds);
        }

        public static bool IsDigit(char value)
        {
            if (value < 128) return value >= '0' && value <= '9';
            return InRanges(value, DigitStarts, DigitEnds);
        }

        public static bool IsLetterOrDigit(char value)
        {
            if (value < 128) return (value >= 'A' && value <= 'Z') ||
                (value >= 'a' && value <= 'z') || (value >= '0' && value <= '9');
            return InRanges(value, LetterStarts, LetterEnds) ||
                InRanges(value, DigitStarts, DigitEnds);
        }

        private static bool InRanges(int value, int[] starts, int[] ends)
        {
            var index = Array.BinarySearch(starts, value);
            if (index >= 0) return true;
            index = ~index - 1;
            return index >= 0 && value <= ends[index];
        }
